 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    axes = {}
    # Each solid 3x3 colored square emits a full horizontal and vertical beam
    # through its center. Locate the square by its nine matching cells.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                axes[color] = (r + 1, c + 1)
    owners = {}
    for color, (r, c) in axes.items():
        for x in range(w):
            owners.setdefault((r, x), set()).add(color)
        for y in range(h):
            owners.setdefault((y, c), set()).add(color)
    for (r, c), colors in owners.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
